export const HTML=`<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>Mini Hosting · Cluster Monitor</title><link rel="stylesheet" href="/style.css"></head><body><main><header><div><div class="eyebrow">MINI HOSTING · ONLINE MONITOR</div><h1>Cụm máy chủ</h1><p class="muted">Giám sát cụm và cấu hình chính sách HA (qua Cloudflare Access)</p></div><div class="right"><span id="cloudStatus" class="pill">Đang kết nối</span><div id="timestamp" class="subtle">—</div></div></header><section class="stats"><div class="panel"><div class="subtle">Node online</div><strong id="online">—</strong><div id="total" class="muted">—</div></div><div class="panel"><div class="subtle">Máy đang phục vụ (quan sát)</div><strong id="serving" class="medium">—</strong><div class="muted">Không phải xác nhận quyền ghi</div></div><div class="panel"><div class="subtle">Tự chuyển vai trò</div><strong id="haAutoBadge" class="medium amber">CHƯA BẬT</strong><div class="muted">Chờ đồng bộ GTID và fencing</div></div></section><section class="panel warning" id="warning">Nếu bộ phân xử HA chưa triển khai và chưa kích hoạt trên cả hai node, website vẫn chạy như trước; không có tự chuyển máy chính.</section><div class="sectionHead"><h2>Các máy trong cụm</h2><button id="refresh">Làm mới</button></div><section class="nodes" id="nodes"><div class="panel muted">Đang nạp node…</div></section><section class="panel pairing"><h2>Thêm node vào Monitor</h2><p class="muted">Bấm tạo mã ghép, sau đó chạy lệnh <code>~/mhc online-enroll MÃ_GHÉP</code> trên node đã cài Cluster Agent. Mã dùng một lần và hết hạn sau 10 phút.</p><div class="pairActions"><button id="pair">Tạo mã ghép 10 phút</button><button id="copy" hidden>Sao chép lệnh</button></div><pre id="pairCode" aria-live="polite"></pre></section><section class="panel" id="haPanel"><h2>Điều khiển máy chủ chính</h2><p class="muted">Cần witness, GTID, đối soát file và fencing được kích hoạt trên hai node. Chọn máy chính không tự bỏ qua các điều kiện này.</p><div class="facts"><div><label for="haMode">Chế độ</label><select id="haMode"><option value="manual">Thủ công</option><option value="auto">Tự động</option></select></div><div><label for="haPreferred">Máy ưu tiên</label><select id="haPreferred"></select></div><div><label for="haRpo">RPO tối đa (giây)</label><input type="number" id="haRpo" min="0" max="300" value="0"></div><div><button id="haSave">Lưu chính sách</button></div></div><p id="haStatus" class="muted">Đang kiểm tra cấu hình witness…</p></section><footer>Thông tin battery/Wi-Fi có thể không khả dụng trên điện thoại chưa cài Termux:API. Máy offline vẫn hiện lần nhận số liệu cuối. Cổng quản trị 9090 và monitor LAN 9091 không mở ra Internet.</footer></main><script src="/app.js"></script></body></html>`;
export const CSS=`select,input{display:block;background:#22354c;color:#fff;border:1px solid #52708e;border-radius:8px;padding:9px;min-width:180px;max-width:100%;margin:5px 0 12px}:root{color-scheme:dark;--bg:#0b1220;--p:#151f2f;--bd:#2a3b52;--text:#f1f5fb;--sub:#9fb0c6;--accent:#80b9ff;--good:#63d5a2;--warn:#ffd079;--bad:#ff8790}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top right,#172a40 0,transparent 52%),var(--bg);color:var(--text);font:15px/1.5 system-ui,-apple-system,'Segoe UI',sans-serif}main{max-width:1160px;margin:auto;padding:24px 16px 56px}header,.sectionHead{display:flex;justify-content:space-between;gap:15px;align-items:center}.eyebrow{font-size:11px;font-weight:750;letter-spacing:.13em;color:var(--accent)}h1{margin:7px 0;font-size:clamp(25px,4vw,34px)}h2{font-size:18px;margin:4px 0 14px}.muted,.subtle{color:var(--sub)}.subtle{font-size:12px}.right{text-align:right}.pill{display:inline-block;border-radius:30px;padding:5px 11px;background:#29344a;font-size:12px;font-weight:700}.pill.good{color:var(--good);background:#153a36}.pill.bad{color:var(--bad);background:#3e2932}.panel{background:var(--p);border:1px solid var(--bd);border-radius:16px;padding:19px;box-shadow:0 9px 24px #0002}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:24px 0}.stats strong{display:block;font-size:30px;margin:6px 0}.stats strong.medium{font-size:20px}.amber{color:var(--warn)}.warning{border-color:#5a4931;color:#e8c985;margin-bottom:25px}.sectionHead{margin-bottom:8px}.nodes{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px}.nodehead{display:flex;justify-content:space-between;gap:10px;align-items:center}.node h3{margin:5px 0 3px;font-size:18px}.role{font-size:11px;border-radius:15px;background:#263850;padding:3px 8px;color:#a9d0ff}.tiny{font-size:12px;color:var(--sub)}.facts{display:grid;grid-template-columns:1fr 1fr;gap:12px;border-top:1px solid var(--bd);padding-top:14px;margin-top:13px}.facts strong{display:block;font-size:17px;font-weight:650}.facts small{display:block;color:var(--sub)}.services{display:flex;flex-wrap:wrap;gap:5px;margin-top:16px}.service{border-radius:7px;background:#28354a;padding:3px 7px;font-size:11px;color:#c3d2e1}.service.run{background:#194335;color:#b2edd2}.service.down{background:#3d2934;color:#ffbfc3}.meter{height:6px;border-radius:6px;background:#304258;margin:5px 0 3px;overflow:hidden}.meter span{display:block;height:100%;background:#88b5fa}.metricSection{padding-top:12px;margin-top:12px;border-top:1px solid var(--bd)}.metricSection h4{margin:0 0 7px;color:#c4d6e7;font-size:12px;text-transform:uppercase;letter-spacing:.05em}.proc{font-size:12px;color:var(--sub);margin-top:3px}.pairing{margin-top:24px}.pairActions{display:flex;gap:8px;flex-wrap:wrap}button{border:1px solid #45617c;background:#254a6d;color:#f4fbff;font:inherit;font-size:13px;font-weight:650;border-radius:9px;padding:9px 12px;cursor:pointer}button:hover{background:#315e87}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#0e1725;border-radius:10px;padding:10px;font-size:12px}pre:empty{display:none}footer{font-size:12px;color:var(--sub);margin:25px 2px}@media(max-width:620px){header{align-items:flex-start}.stats{grid-template-columns:1fr}.stats strong{font-size:24px}.nodes{grid-template-columns:1fr}.facts strong{font-size:15px}}`;
export const CLIENT_JS=String.raw`'use strict';
const $=x=>document.getElementById(x),safe=x=>String(x??'—'),esc=x=>safe(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bytes=n=>Number.isFinite(n)&&n>=0?(n>=2**30?(n/2**30).toFixed(1)+' GiB':(n/2**20).toFixed(0)+' MiB'):'—';
const date=s=>s?new Date(s).toLocaleString('vi-VN',{hour12:false}):'Chưa có';
const dur=n=>Number.isFinite(n)?Math.floor(n/86400)+' ngày '+Math.floor(n%86400/3600)+' giờ':'—';
const val=(n,s='')=>Number.isFinite(n)?n+s:'—';
const bar=(used,total)=>Number.isFinite(used)&&Number.isFinite(total)&&total>0?'<div class="meter"><span style="width:'+Math.max(0,Math.min(100,100*used/total)).toFixed(1)+'%"></span></div>':'';
function card(node){const x=node.health||{},m=x.monitor||{},r=m.memory||{},d=m.disk||{},b=m.battery||{},wifi=m.wifi||{},p=Array.isArray(m.nodeProcesses)?m.nodeProcesses:[],s=x.services||{};
 const live=node.online,serving=live&&s.miniWeb==='run'&&s.tunnel==='run';const tagline=serving?'Có dấu hiệu đang phục vụ':s.miniWeb==='run'?'Web cục bộ đang chạy':'Không phục vụ website';
 return '<article class="panel node"><div class="nodehead"><span class="role">'+esc(x.declaredRole==='primary'?'CẤU HÌNH: PRIMARY':'CẤU HÌNH: STANDBY')+'</span><span class="pill '+(live?'good':'bad')+'">'+(live?'● ONLINE':'● OFFLINE')+'</span></div><h3>'+esc(node.label)+'</h3><div class="tiny">'+esc(tagline)+' · Cập nhật '+esc(date(node.lastSeenAt))+'</div><div class="facts">'+
 '<div><small>Pin</small><strong>'+val(b.percentage,'%')+'</strong><div class="tiny">'+esc(b.status||'Không có API')+'</div></div>'+
 '<div><small>Nhiệt độ pin</small><strong>'+val(b.temperatureC,'°C')+'</strong></div>'+
 '<div><small>RAM còn khả dụng</small><strong>'+bytes(r.available)+'</strong>'+bar((r.total??0)-(r.available??0),r.total)+'</div>'+
 '<div><small>Bộ nhớ còn trống</small><strong>'+bytes(d.available)+'</strong>'+bar(d.used,d.total)+'</div>'+
 '<div><small>Thời gian hoạt động</small><strong>'+esc(dur(m.systemUptimeSec))+'</strong></div>'+
 '<div><small>Wi-Fi</small><strong>'+esc(wifi.status||'unknown')+'</strong><small>'+val(wifi.rssi,' dBm')+'</small></div>'+
 '</div><div class="services">'+Object.entries({DB:s.mysqld,Web:s.miniWeb,Tunnel:s.tunnel,Panel:s.panel,Sync:s.standbySync}).map(([k,v])=>'<span class="service '+(v==='run'?'run':v==='down'?'down':'')+'">'+esc(k)+': '+esc(v||'unknown')+'</span>').join('')+'</div>'+
 '<div class="metricSection"><h4>Đồng bộ dữ liệu</h4><div class="tiny">Snapshot: '+esc(x.snapshotApplied||x.backupName||'Chưa có')+'</div><div class="tiny">Độ trễ: '+(Number.isFinite(x.syncAgeSeconds)?x.syncAgeSeconds+' giây':'Chưa đo được')+'</div></div>'+
 '<div class="metricSection"><h4>Tiến trình Node.js ('+p.length+')</h4>'+p.slice(0,6).map(y=>'<div class="proc">'+esc(y.name||'Node.js')+' · '+bytes(y.rssBytes)+'</div>').join('')+'</div></article>';
}
let loading=false;
async function load(){if(loading)return;loading=true;try{const r=await fetch('/api/nodes',{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);const x=await r.json(),nodes=x.nodes||[],on=nodes.filter(x=>x.online).length;
 $('online').textContent=on;$('total').textContent=nodes.length+' node đã đăng ký';const serv=nodes.filter(x=>x.online&&x.health?.services?.miniWeb==='run'&&x.health?.services?.tunnel==='run');
 $('serving').textContent=serv.length===1?serv[0].label:serv.length===0?'Chưa xác minh':'CẢNH BÁO: '+serv.length+' node';
 $('warning').textContent=serv.length>1?'CẢNH BÁO: Có nhiều node báo Web + Tunnel cùng chạy. Cần kiểm tra nguy cơ split-brain.':x.warning;
 $('nodes').innerHTML=nodes.length?nodes.map(card).join(''):'<div class="panel">Chưa có node. Tạo mã ghép bên dưới để kết nối.</div>';
 const chosen=$('haPreferred').value;$('haPreferred').innerHTML=nodes.filter(n=>n.health?.clusterId).map(n=>'<option value="'+esc(n.nodeId)+'">'+esc(n.label)+'</option>').join('');if(chosen)$('haPreferred').value=chosen;
 $('cloudStatus').textContent='● MONITOR ONLINE';$('cloudStatus').className='pill good';$('timestamp').textContent='Cập nhật '+date(x.asOf);
 }catch(e){$('cloudStatus').textContent='● MONITOR ERROR';$('cloudStatus').className='pill bad';$('timestamp').textContent=String(e.message);}finally{loading=false;}}
async function loadHa(){try{const r=await fetch('/api/ha',{cache:'no-store'}),x=await r.json();if(!r.ok)throw Error(x.error||'HTTP '+r.status);$('haMode').value=x.mode;$('haAutoBadge').textContent=x.mode==='auto'?'AUTO (đã cấu hình)':'MANUAL (đã cấu hình)';$('haRpo').value=x.maxRpoSeconds;$('haPreferred').value=x.preferredNodeId||'';$('haStatus').textContent='Máy đang giữ lease: '+(x.leaderId||'chưa có')+' · Term '+x.term+' · Hết hạn '+(x.expiresAt?new Date(x.expiresAt).toLocaleString('vi-VN'):'—');}catch(e){$('haStatus').textContent='HA chưa sẵn sàng: '+e.message;}}
async function saveHa(){const v={mode:$('haMode').value,preferredNodeId:$('haPreferred').value,maxRpoSeconds:Number($('haRpo').value)};
try{const r=await fetch('/api/ha/config',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(v)}),x=await r.json();if(!r.ok)throw Error(x.error||'HTTP '+r.status);$('haStatus').textContent='Đã lưu chính sách; thiết bị chỉ chuyển khi đủ lease, GTID và fencing.';loadHa();}catch(e){$('haStatus').textContent='Không thay đổi: '+e.message;}}
$('haSave').onclick=saveHa;
$('refresh').onclick=load;
$('pair').onclick=async()=>{try{const r=await fetch('/api/pair',{method:'POST'});if(!r.ok)throw Error('HTTP '+r.status);const x=await r.json();$('pairCode').textContent=x.pairingCode+'\n\n~/mhc online-enroll '+x.pairingCode;$('copy').hidden=false;$('copy').onclick=()=>navigator.clipboard.writeText('~/mhc online-enroll '+x.pairingCode);}catch(e){$('pairCode').textContent='Không thể tạo mã: '+e.message;}};
load();loadHa();setInterval(()=>{if(document.visibilityState==='visible'){load();loadHa();}},20000);`;
